 void WireDrops(Control control){control.AllowDrop=true;control.DragEnter+=(s,e)=>{if(!busy&&e.Data.GetDataPresent(DataFormats.FileDrop))e.Effect=DragDropEffects.Copy;};control.DragDrop+=(s,e)=>{if(!busy&&e.Data.GetDataPresent(DataFormats.FileDrop)){AddFiles((string[])e.Data.GetData(DataFormats.FileDrop));ShowPage(1);}};foreach(Control child in control.Controls)WireDrops(child);}
 static System.Threading.Tasks.Task StaTask(Action action){var completion=new System.Threading.Tasks.TaskCompletionSource<object>();var worker=new Thread(()=>{try{action();completion.SetResult(null);}catch(OperationCanceledException){completion.SetCanceled();}catch(Exception e){completion.SetException(e);}}){IsBackground=true};worker.SetApartmentState(ApartmentState.STA);worker.Start();return completion.Task;}
