 void ScanSmart(){string root=scanRoot.Text;int mode=scanMode.SelectedIndex,days=(int)age.Value;long minimum=(long)large.Value*1048576;Work("扫描空间候选项",t=>{var r=Engine.ScanCleanup(root,mode,days,minimum,t,Progress);BeginInvoke(new Action(()=>{smart.BeginUpdate();smart.Items.Clear();foreach(var hit in r.Items.OrderByDescending(x=>x.Bytes)){var row=new ListViewItem(new[]{hit.Path,hit.Kind,Engine.SizeText(hit.Bytes),hit.WriteStamp==0?"—":DateTime.FromFileTimeUtc(hit.WriteStamp).ToLocalTime().ToString("yyyy-MM-dd HH:mm")}){Tag=hit,ToolTipText=hit.Path};smart.Items.Add(row);}smart.EndUpdate();scanSummary.Text="找到 "+r.Items.Count+" 项 · "+Engine.SizeText(r.Items.Sum(x=>x.Bytes))+" · 检查 "+r.Visited+" 项"+(r.Limit?" · 已达到扫描上限，请缩小范围":"")+" · 跳过/错误 "+r.Warnings.Count;Say(scanSummary.Text);foreach(var w in r.Warnings)Say("扫描跳过："+w);}));});}
 void CleanSmart(){var rows=smart.CheckedItems.Cast<ListViewItem>().Where(r=>r.Tag is CleanCandidate).ToArray();if(rows.Length==0){BrandDialogs.Show("请核对并勾选候选项。");return;}bool recycle=smartRecycle.Checked;if(!Confirm("清理空间候选项","处理 "+rows.Length+" 个勾选项目。\n"+(recycle?"文件移入回收站；空文件夹直接移除。":"文件将永久删除，不进入回收站。")+"\n文件变化或空文件夹已非空时跳过。",true))return;var targets=rows.Select(x=>(CleanCandidate)x.Tag).ToArray();Work("清理空间候选项",t=>{for(int i=0;i<targets.Length;i++){t.ThrowIfCancellationRequested();int index=i;try{Engine.DeleteCandidate(targets[i],recycle,t);Say("已清理："+targets[i].Path);BeginInvoke(new Action(()=>{rows[index].Checked=false;rows[index].Tag=null;rows[index].SubItems[3].Text="清理完成";}));}catch(OperationCanceledException){throw;}catch(Exception ex){Say("已跳过："+targets[i].Path+" · "+ex.Message);BeginInvoke(new Action(()=>rows[index].SubItems[3].Text="跳过："+ex.Message));}}});}
 void ExportList(ListView list,string name){using(var d=new SaveFileDialog{Filter="CSV 表格|*.csv",FileName="景·除-"+name+"-"+DateTime.Now.ToString("yyyyMMdd")+".csv"})if(d.ShowDialog()==DialogResult.OK)try{Engine.ExportCsv(d.FileName,list.Columns.Cast<ColumnHeader>().Select(x=>x.Text).ToArray(),list.Items.Cast<ListViewItem>().Select(x=>x.SubItems.Cast<ListViewItem.ListViewSubItem>().Select(y=>y.Text).ToArray()));Say("已导出："+d.FileName);}catch(Exception e){BrandDialogs.Show(e.Message);}}
 void BuildStartup(){var p=Page();p.Controls.Add(Note("同时显示注册表 Run 项、用户/公共启动文件夹以及已禁用的启动文件。\n注册表禁用先导出整个 Run 键；文件禁用保存副本，恢复时不覆盖同名文件。",62));var bar=Toolbar(p,55);bar.Controls.Add(Button("刷新启动项",(s,e)=>LoadStartup()));bar.Controls.Add(Button("禁用选中项",(s,e)=>ChangeStartup(false)));bar.Controls.Add(Button("恢复文件启动项",(s,e)=>ChangeStartup(true)));bar.Controls.Add(Button("导出 CSV",(s,e)=>ExportList(startup,"启动项")));startup=List(p,new[]{"启动项名称","命令 / 路径","来源 / 状态"},new[]{210,460,210},false);}
 System.Collections.Generic.List<Bitmap> startupBitmaps=new System.Collections.Generic.List<Bitmap>();
 void RefreshStartup(CancellationToken token){var rows=new System.Collections.Generic.List<ListViewItem>();var images=new System.Collections.Generic.List<Bitmap>();try{foreach(var r in Engine.Startup()){token.ThrowIfCancellationRequested();rows.Add(new ListViewItem(new[]{r.ValueName,r.Description,"注册表 / "+(r.Hive==Microsoft.Win32.RegistryHive.CurrentUser?"当前用户":"所有用户")+" / "+(r.View==Microsoft.Win32.RegistryView.Registry64?"64":"32")}){Tag=r});images.Add(SoftwareIcons.Startup(r));}foreach(var f in Engine.StartupFiles()){token.ThrowIfCancellationRequested();rows.Add(new ListViewItem(new[]{f.Name,f.Path,(f.Scope=="User"?"用户":"公共")+"启动文件夹 / "+(f.Disabled?"已禁用":"启用中")}){Tag=f});images.Add(SoftwareIcons.Startup(f));}BeginInvoke(new Action(()=>SetStartupRows(rows,images)));}catch{foreach(var b in images)b.Dispose();throw;}}
 void SetStartupRows(System.Collections.Generic.List<ListViewItem> rows,System.Collections.Generic.List<Bitmap> images){var list=new ImageList{ColorDepth=ColorDepth.Depth32Bit,ImageSize=new Size(32,34)};foreach(var b in images)list.Images.Add(b);var old=startup.SmallImageList;var previous=startupBitmaps;startup.BeginUpdate();try{startup.Items.Clear();startup.SmallImageList=list;startupBitmaps=images;for(int i=0;i<rows.Count;i++){rows[i].ImageIndex=i;startup.Items.Add(rows[i]);}}finally{startup.EndUpdate();}if(old!=null)old.Dispose();foreach(var b in previous)b.Dispose();Say("已读取启动项及图标："+rows.Count);}
 void LoadStartup(){Work("读取开机启动项与图标",t=>RefreshStartup(t));}
 void ChangeStartup(bool enable){if(startup.SelectedItems.Count!=1){BrandDialogs.Show("请选中一个启动项。");return;}object obj=startup.SelectedItems[0].Tag;var reg=obj as RegItem;var file=obj as StartupFile;if(enable&&reg!=null){BrandDialogs.Show("注册表启动项请在备份与日志页导入对应备份。恢复会合并备份中的所有值。");return;}if(file!=null&&file.Disabled==!enable){BrandDialogs.Show(enable?"此文件启动项已经启用。":"此文件启动项已经禁用。");return;}if(!Confirm(enable?"恢复启动项":"禁用启动项",obj+"\n\n"+(reg!=null?"将备份整个 Run 键后删除所选值。":"将"+(enable?"恢复原文件，不覆盖同名文件。":"备份文件后从启动文件夹移除。")),false))return;Work(enable?"恢复文件启动项":"禁用启动项",t=>{if(reg!=null)Engine.DisableStartup(reg);else if(enable)Engine.EnableStartupFile(file);else Engine.DisableStartupFile(file);Say("启动项已更新："+obj);RefreshStartup(t);});}
